function CollapsibleSection() {
  const [isOpen, setIsOpen] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);
  const [contentHeight, setContentHeight] = useState(0);

  useEffect(() => {
    if (contentRef.current) {
      setContentHeight(contentRef.current.scrollHeight);
    }
  }, []);

  return (
    <div className="mb-16">
      {/* Top divider */}
      <div className="h-px bg-white/[0.06] mb-0" />

      <button
        onClick={() => setIsOpen(!isOpen)}
        className="w-full flex items-center gap-3 py-5 group cursor-pointer text-left"
      >
        {/* Minimal plus/minus toggle */}
        <span className="font-['JetBrains_Mono'] text-[13px] text-white/30 w-5 shrink-0 group-hover:text-white/50 transition-colors">
          [{isOpen ? "\u2212" : "+"}]
        </span>
        <span className="font-['JetBrains_Mono'] text-[11px] md:text-[12px] tracking-[1.5px] uppercase text-white/40 group-hover:text-white/60 transition-colors">
          What Is Behavioral Architecture?
        </span>
      </button>

      {/* Expandable content */}
      <div
        className="overflow-hidden transition-[max-height] duration-500 ease-in-out"
        style={{ maxHeight: isOpen ? `${contentHeight}px` : "0px" }}
      >
        <div ref={contentRef} className="pb-6 pl-8">
          <p className="font-['JetBrains_Mono'] text-[10px] md:text-[11px] leading-[2] text-white/30 max-w-2xl">
            STRIDE is built on behavioral architecture and voluntary identity reinforcement. Instead of manipulating users or relying on dopamine-driven gamification, we design the environment, friction, and interaction language to strengthen internal discipline and self-authorship. Training becomes the delivery vehicle — not the objective. Every action, from session start to completion feedback, is engineered to reinforce identity at the execution level. It aligns structure and language so users consciously participate in becoming stronger — physically and psychologically.
          </p>
        </div>
      </div>

      {/* Bottom divider */}
      <div className="h-px bg-white/[0.06]" />
    </div>
  );
}

